// Code generated by packages/kit-compose/src/organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
// Data of MediaFrame: long values (pictures as data URIs) kept out of the component file.

export const PLACEHOLDER: Record<string, string> = {
  "light": "data:image/svg+xml;base64,",
  "dark": "data:image/svg+xml;base64,",
};

// Code generated by packages/kit-compose/src/organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
/**
 * A picture in a fixed ratio that follows the theme. `src` is the picture of the light theme, `darkSrc` the one
 * of the dark theme (without it the dark theme shows `src`). Without both (an empty string counts as none) it
 * shows the built-in neutral placeholders (base64 data URIs, one light and one dark), so a page can be laid out
 * before it has pictures; the placeholder is decorative (`alt` is empty), stands in for a real `src` and is
 * switched by the theme token. A real picture gets `alt` and loads lazily. `ratio` comes from the recipe; the
 * corners are the plain theme radius. `srcset` lists sizes of `src` (written by an export, e.g. WebP 960w /
 * 1280w / 1920w) and `sizes` says how wide the picture is shown, so the browser picks a size; the dark picture
 * takes the srcset only when it is `src` (no `darkSrc`).
 */
import { type JSX } from "solid-js";
import { Box, Image } from "../compose";
import { at, cn, srcsetOf, urlOf, variants } from "../utils";
import { PLACEHOLDER } from "./media-frame.assets";

/** MediaFrame: the classes of each value (shadcn/cva style). */
export const mediaFrameVariants = variants({
  base: "relative w-full overflow-hidden bg-muted text-muted-foreground inset-ring inset-ring-border rounded",
  variants: {
    ratio: {
      "16/9": "aspect-video",
      "4/3": "aspect-4/3",
      "1/1": "aspect-square",
      "3/4": "aspect-3/4",
      "21/9": "aspect-21/9",
    },
  },
  defaultVariants: { ratio: "16/9" },
});

export type MediaFrameProps = {
  alt: string;
  src?: string;
  darkSrc?: string;
  ratio?: "16/9" | "4/3" | "1/1" | "3/4" | "21/9";
  srcset?: string;
  sizes?: string;
  class?: string;
};

export function MediaFrame({
  alt,
  src,
  darkSrc,
  ratio = "16/9",
  srcset,
  sizes = "100vw",
  class: className,
}: MediaFrameProps) {
  const lightSrc = src ? src : at(PLACEHOLDER, "light");
  const nightSrc = darkSrc ? darkSrc : (src ? src : at(PLACEHOLDER, "dark"));
  const shownAlt = src ? alt : "";
  const loadHint = src ? "lazy" : undefined;
  const decodeHint = src ? "async" : undefined;
  const lightSet = (src && srcset) ? srcset : undefined;
  const nightSet = darkSrc ? undefined : lightSet;
  const lightSizes = lightSet ? sizes : undefined;
  const nightSizes = nightSet ? sizes : undefined;
  return (
    <Box
      class={cn(mediaFrameVariants({ ratio: ratio }), className)}
      data-slot="media-frame"
      data-placeholder={(src ? "false" : "true")}
    >
      <Image
        src={urlOf(lightSrc, true)}
        srcset={srcsetOf(lightSet)}
        sizes={lightSizes}
        alt={shownAlt}
        loading={loadHint}
        decoding={decodeHint}
        class="absolute inset-0 size-full object-cover dark:hidden"
        data-theme-src="light"
      />
      <Image
        src={urlOf(nightSrc, true)}
        srcset={srcsetOf(nightSet)}
        sizes={nightSizes}
        alt={shownAlt}
        loading={loadHint}
        decoding={decodeHint}
        class="absolute inset-0 hidden size-full object-cover dark:block"
        data-theme-src="dark"
      />
    </Box>
  );
}
